    public static class ZygmuntKrasiński
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Galilaee, vicisti!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Gwiazdy wokoło twojej głowy – pod twoimi nogi fale morza – na falach morza tęcza przed tobą pędzi i rozdziela mgły – co ujrzysz, jest twoim – brzegi, miasta i ludzie tobie się przynależą – niebo jest twoim – chwale twojej niby nic nie zrówna.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Jakżeś mi piękna w osłabieniu swoim – w nieładzie kwiaty i perły na włosach twoich – płoniesz ze wstydu i znużenia – o, wiecznie, wiecznie będziesz pieśnią moją.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Bezkarnie deptać można po ciele, z którego wyleciała dusza.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Kto się poświęci dla dobra ludzi, powinien o ich sądzie zapomnieć.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Rzeczywistość się pomału\nW świat przemienia ideału,\nW sen ze srebra i kryształu.\nDaj mi teraz marzyć, daj!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Zgińcie, me pieśni – wstańcie, Czyny moje!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Dość już długo – dość już długo\nBrzmiał na strunach wieszczów żal!\nCzas uderzyć w strunę drugą,\nW czynów stal!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Jeden tylko, jeden cud:\nZ Szlachtą polską – polski Lud,\nJak dwa chóry – jedno pienie! –\nWszystko inne – złudą złud!\nWszystko inne – plamą plam!\nI ojczyzna tylko tam! –\nJeden tylko, jeden cud:\nZ Szlachtą polską – polski Lud.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Miłość bez granic – to życie bez końca.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Niczym Sybir – niczym knuty\nI cielesnych tortur król!\nLecz narodu duch otruty –\nTo dopiero bólów ból!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Prawdą jest, żem na wieki Twój, w każdym miejscu i położeniu Twój, tylko Twój!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Ręce i stopy Twoje oblewam łzami. Kocham Cię, kocham, kocham, i teraz i na wieki Twój jestem. – Biedny Zyg.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Smętnem życie takie, Dyszo najlepsza moja, – ale jakie życie nie jest smętnem? Są chwile piorunowe – lecz, jak piorun, ogromne światłem i znikome zarazem – szczęścia!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Wydaje mi się świętokradztwem nakłonić ucho do dźwięków, nie z Twoich ust.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Bądź cierpliwością – tą panią niedoli –\nCo gmach swój stwarza z niczego – powoli!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Bo na tym świecie wszystko, co marzyłem,\nPrzeszło jak chmura i znikło w oddali.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Bo żyć na darmo – to jest żyć bez ciebie!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Cokolwiek będzie, cokolwiek się stanie, Jedno wiem tylko: sprawiedliwość będzie, Jedno wiem tylko: Polska zmartwychwstanie.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Cudze śmieszności, choć nigdy z własnych nie wyleczą, są jednak silnym lekarstwem.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Czas ma nadzwyczaj coś gorzkiego w sobie!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Dla mnie miłość jest tylko piosenką, wygraną na fletni w przerwach między czynnościami życiowemi; a jednak oddałbym wszystko, by miłość była mojem życiem.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Duma bez pokory, to próżność; pokora bez dumy to podłość.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Gdybym ją posiadł, świat ubrałbym w czary,\nA że jej nie mam, jestem wierszokleta.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "I świat ten cały był giełdą bez Boga.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Już się ma pod koniec starożytnemu światu – wszystko, co w nim żyło, psuje się, rozprzęga i szaleje – bogi i ludzie szaleją… Fatum jedno spokojne, niewzruszone, ''rozum'' nieubłagany świata, patrzy z wysoka na wiry ziemi i nieba.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Kampania rzymska! to świat mej młodości!\nDuch mój wzrósł w siłę tam, gdzie Tyber płynie!\nHarfy sitrunami na natchnienia włości\nPodbiłem sobie wiekową pustynię!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Każda nowość razi, obraża nawet, zanim da się rozpoznać.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Ledwom cię poznał, już cię żegnać muszę,\nA żegnam ciebie, jak gdybym przez wieki\nŻył z tobą razem i kochał twą duszę,\nA teraz jechał w jakiś kraj daleki.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Miłość jest darem nieba, nadużyta – piekła!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Nie jest czynem – rzeź dziecinna! Nie jest czynem – wyniszczenie!", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Nieszczęście jest jak miłość, wiąże ludzi ze sobą.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "Pycha – to karłów zbuntowanych siła.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "U ludzi marne słowo jest także potęgą.", Author = "Zygmunt Krasiński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zygmunt_Krasiński", Text = "W ciągłej przykładu i słowa postaci\nrozdawaj siebie samego swej braci.\nMnóż się ty jeden przez czyny żyjące,\na będą z Ciebie jednego… tysiące", Author = "Zygmunt Krasiński" },
        };
    }
